ch = channel('print')
ch.exchange_declare('events', 'topic',
                    durable=True)
binds = {'print': 'act.*', 'audit': '#',
         'mail': '*.signed'}
for q, key in binds.items():
    ch.queue_declare(q, durable=True,
                     arguments=QUORUM)
    ch.queue_bind(q, 'events', key)
keys = ['act.new', 'act.signed',
        'stock.signed', 'act.new.urgent']
for k in keys:
    ch.basic_publish('events', k, k)
res = {k: [] for k in keys}
for q in binds:
    while True:
        m, _, body = ch.basic_get(q, True)
        if m is None:
            break
        res[body.decode()].append(q)
